                  >
                    <span className="font-display font-bold text-[#414141] group-hover:text-[#C8102E]">{pacer.first_name[0]}</span>
                  </motion.div>
                  <span className="mt-2 text-xs font-semibold bg-white/80 px-2 py-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity">
                    {pacer.first_name}
                  </span>
                </motion.div>
              );
            })}
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
};

