            <div className={`w-5 h-5 mt-0.5 rounded border flex items-center justify-center shrink-0 transition-colors ${ferpaChecked ? 'bg-[#C8102E] border-[#C8102E]' : 'border-[#414141]'}`}>
              {ferpaChecked && <lucide.Check size={14} color="white" />}
            </div>
            <p className="text-sm text-[#414141] leading-snug">
              I consent to share my anonymized trajectory and week-6 CLR events with {pacer.first_name} {pacer.last_name} for 8-week segment pacing.
            </p>
          </div>
        </div>

        <div className="p-6 border-t border-[#D9D9D9] flex justify-end gap-4 bg-[#F7F7F7]">
          <button className="btn-ghost" onClick={onCancel} disabled={isSubmitting}>Cancel</button>
          <button className="btn-primary w-48 flex justify-center items-center" onClick={handleConfirm} disabled={!ferpaChecked || isSubmitting}>
            {isSubmitting ? <lucide.Loader2 className="animate-spin" size={18} /> : 'Confirm Subscription'}
          </button>
        </div>
      </motion.div>
    </div>
  );
};

// 4. Teams Chat Nudge (Depth-First 2)
const TeamsChatNudge = ({ pacerId, student, onLogEvent }) => {
  const [nudgeData, setNudgeData] = React.useState(null);
  const [chatHistory, setChatHistory] = React.useState([
    { id: 1, sender: 'pacer', text: `Hey Priya — Copilot flagged that week 6 was rough for both of us. The recursion stuff almost made me switch majors. Happy to share what worked.` },
    { id: 2, sender: 'student', text: `Honestly yes — what worked?` }
  ]);
  const [isLoading, setIsLoading] = React.useState(true);
  const pacer = SEED_PACERS.find(p => p.id === pacerId) || SEED_PACERS[0];

  React.useEffect(() => {
    let mounted = true;
    const fetchNudge = async () => {
      try {
        const prompt = `Segment week: 7. Pacer historical event: First PR merged. Generate nudge and replies.`;
        const res = await callAIWithVS(
          "You are a Copilot assistant facilitating a mentorship chat. Generate a weekly nudge anchored to the pacer's historical CLR event for this week. Provide 1 anchor prompt and 3 suggested replies for the student. Output JSON: { nudge_text: string, suggested_replies: string[] }",
          prompt
        );
        const parsed = JSON.parse(res.text);
        if (mounted) setNudgeData(parsed);
      } catch (e) {
        if (mounted) setNudgeData({
          nudge_text: `Week 7 of your segment. ${pacer.first_name}, in your week 7 you logged the GitHub-collab milestone. Priya, want to share where you are on collaborative coding this week?`,
          suggested_replies: ["I'm opening my first PR today!", "Still struggling with Git basics.", "Can we review my repo?"]
        });
      } finally {
        if (mounted) setIsLoading(false);
      }
    };
    fetchNudge();
    return () => { mounted = false; };
  }, [pacer]);

  const handleReply = (text) => {
    setChatHistory([...chatHistory, { id: Date.now(), sender: 'student', text }]);
    setNudgeData(null); // Dissolve card
  };

  return (
    <div className="flex flex-col h-full bg-[#F0F0F0]">
      {/* Teams Header Replica */}
      <div className="h-14 bg-white border-b border-[#D9D9D9] flex items-center px-4 justify-between shrink-0">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-full bg-[#C8102E] text-white flex items-center justify-center font-bold text-sm">{pacer.first_name[0]}</div>
          <div>
            <h2 className="text-sm font-bold">{pacer.first_name} {pacer.last_name}</h2>
            <p className="text-xs text-[#737373]">Pacer • {pacer.current_employer}</p>
          </div>
        </div>
        <div className="flex gap-4 text-[#414141]">
          <lucide.Video size={18} />
          <lucide.Phone size={18} />
        </div>
      </div>

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        <div className="text-center text-xs text-[#737373] font-mono mb-8">Tuesday, 4:00 PM</div>

        {chatHistory.map(msg => (
          <div key={msg.id} className={`flex ${msg.sender === 'student' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[70%] p-3 rounded-md text-sm ${msg.sender === 'student' ? 'bg-[#E5E5EA] text-black' : 'bg-white border border-[#D9D9D9] text-black'}`}>
              {msg.text}
            </div>
          </div>
        ))}

        <AnimatePresence>
          {nudgeData && !isLoading && (
            <motion.div 
              initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }}
              className="max-w-[80%] bg-white border border-[#D9D9D9] rounded-md shadow-sm overflow-hidden"
            >
              <div className="bg-[#F7F7F7] px-3 py-2 border-b border-[#D9D9D9] flex items-center gap-2">
                <lucide.Sparkles size={14} className="text-[#C8102E]" />
                <span className="text-xs font-semibold text-[#414141]">Drafted with Copilot, sent by {pacer.first_name}</span>
              </div>
              <div className="p-4">
                <p className="text-sm text-[#000000] mb-4">{nudgeData.nudge_text}</p>
                <div className="flex flex-wrap gap-2">
                  {nudgeData.suggested_replies.map((reply, i) => (
                    <motion.button
                      key={i} whileTap={{ scale: 0.95 }} onClick={() => handleReply(reply)}
                      className="px-3 py-1.5 bg-[#F7F7F7] border border-[#D9D9D9] rounded-full text-xs font-semibold text-[#414141] hover:bg-white hover:border-[#C8102E] transition-colors"
                    >
                      {reply}
                    </motion.button>
                  ))}
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {isLoading && (
          <div className="max-w-[80%] bg-white border border-[#D9D9D9] rounded-md p-4 space-y-3">
            <Skeleton className="h-4 w-1/3" />
            <Skeleton className="h-10 w-full" />
            <div className="flex gap-2"><Skeleton className="h-8 w-24 rounded-full" /></div>
          </div>
        )}
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white border-t border-[#D9D9D9]">
        <div className="flex items-center gap-2 bg-[#F7F7F7] border border-[#D9D9D9] rounded-md p-2">
          <input type="text" placeholder="Type a new message" className="flex-1 bg-transparent border-none outline-none text-sm px-2" disabled />
          <button className="p-2 text-[#737373] hover:text-[#C8102E] transition-colors" onClick={onLogEvent} title="Log CLR Event">
            <lucide.PlusCircle size={20} />
          </button>
          <button className="p-2 text-[#737373]"><lucide.Send size={20} /></button>
        </div>
      </div>
    </div>
  );
};

// 5. Milestone Celebration
