      >
        <div className="h-64 bg-[#F7F7F7] relative flex items-center justify-center">
          {isLoading ? (
            <div className="flex flex-col items-center text-[#737373]">
              <lucide.Loader2 className="animate-spin mb-2" size={24} />
              <span className="text-sm font-mono">Generating celebration...</span>
            </div>
          ) : (
            imgUrl ? <img src={imgUrl} alt="Celebration" className="w-full h-full object-cover" /> : <div className="w-full h-full bg-gradient-to-br from-[#FBE7EA] to-white" />
          )}
        </div>

        <div className="p-8 text-center">
          <Badge variant="success">Milestone Reached</Badge>
          <h2 className="text-3xl font-display mt-4 mb-2 text-[#000000]">First PR Merged</h2>
