          <div className="flex justify-center gap-4 mb-8">
            <button className="w-12 h-12 rounded-full bg-[#F7F7F7] border border-[#D9D9D9] flex items-center justify-center text-xl hover:bg-[#FBE7EA] hover:border-[#C8102E] transition-all">🎉</button>
            <button className="w-12 h-12 rounded-full bg-[#F7F7F7] border border-[#D9D9D9] flex items-center justify-center text-xl hover:bg-[#FBE7EA] hover:border-[#C8102E] transition-all">👊</button>
          </div>

          <button className="btn-ghost" onClick={onReturn}>Return to Canvas</button>
