  const [promptText, setPromptText] = React.useState('');
  const [isLoading, setIsLoading] = React.useState(false);

  React.useEffect(() => {
    let mounted = true;
    const fetchPrompt = async () => {
      setIsLoading(true);
      try {
        const res = await callAIWithVS(
          "You are an advisor's Copilot. Review a student's trajectory health, active pacer status, and recent CLR events. Compose a single-sentence coaching prompt for the advisor to use in their next 1:1. Output JSON: { coaching_prompt: string }",
          `Student: ${selectedStudent.first_name}. Health: ${selectedStudent.trajectory_health}. Generate 1-line prompt.`
        );
        const parsed = JSON.parse(res.text);
