      {/* Main Content */}
      <div className="flex-1 p-8 bg-white flex flex-col">
        <div className="mb-8">
          <h1 className="text-3xl font-display font-bold mb-2">{selectedStudent.first_name} {selectedStudent.last_name}</h1>
          <p className="text-[#414141]">{selectedStudent.declared_major} • {selectedStudent.declared_track}</p>
        </div>

        <motion.div 
          key={selectedStudent.id}
          initial={{ backgroundColor: '#F7F7F7' }} animate={{ backgroundColor: '#FFFFFF' }} transition={{ duration: 0.5 }}
