        >
          <div className="flex items-center gap-2 mb-4">
            <lucide.Sparkles size={16} className="text-[#C8102E]" />
            <h3 className="font-bold text-sm uppercase tracking-wider text-[#414141]">This Week's Coaching Prompt</h3>
