        <div className="flex-1 border border-[#D9D9D9] rounded-md bg-[#F7F7F7] flex items-center justify-center text-[#737373]">
          <div className="text-center">
            <lucide.LineChart size={32} className="mx-auto mb-2 opacity-50" />
            <p className="text-sm font-mono">Anonymized Canvas Preview</p>
          </div>
        </div>
      </div>
    </div>
