// --- MAIN APP ---
const App = () => {
  const [currentScreen, setCurrentScreen] = useSessionStorage('currentScreen', 'trajectory_canvas');
  const [selectedPacerId, setSelectedPacerId] = useSessionStorage('selectedPacerId', null);
  const [ferpaGranted, setFerpaGranted] = useSessionStorage('ferpaGranted', false);
  const [activeSegmentId, setActiveSegmentId] = useSessionStorage('activeSegmentId', SEED_STUDENTS[0].active_segment_id);

  // The primary persona
  const student = SEED_STUDENTS[0];

  const navigate = (screen) => setCurrentScreen(screen);

  const renderScreen = () => {
    switch (currentScreen) {
      case 'trajectory_canvas':
        return <TrajectoryCanvas navigate={navigate} student={student} onSelectPacer={(id) => { setSelectedPacerId(id); navigate('pacer_detail'); }} />;
      case 'pacer_detail':
        return <PacerDetail pacerId={selectedPacerId || 'alum-001'} student={student} onClose={() => navigate('trajectory_canvas')} onSubscribe={(id) => { setSelectedPacerId(id); navigate('subscribe_modal'); }} />;
      case 'subscribe_modal':
        return <SubscribeModal pacerId={selectedPacerId || 'alum-001'} onCancel={() => navigate('pacer_detail')} onConfirm={() => { setFerpaGranted(true); navigate('teams_chat_nudge'); }} />;
      case 'teams_chat_nudge':
        return <TeamsChatNudge pacerId={selectedPacerId || 'alum-001'} student={student} onLogEvent={() => navigate('milestone_celebration')} />;
      case 'milestone_celebration':
        return <MilestoneCelebration onReturn={() => navigate('trajectory_canvas')} />;
      case 'advisor_coach_view':
        return <AdvisorCoachView />;
      default:
        return <TrajectoryCanvas navigate={navigate} student={student} onSelectPacer={() => {}} />;
    }
  };

  return (
    <div className="w-full h-screen overflow-hidden flex flex-col relative">
      <GlobalStyles />

      {/* Demo Controls */}
      <div className="fixed top-4 right-4 z-[100] bg-white border border-[#D9D9D9] shadow-lg rounded-md p-2 flex gap-2 items-center">
        <label className="text-[10px] font-bold text-[#737373] uppercase tracking-wider">Jump to:</label>
        <select 
          className="text-xs border-none bg-transparent focus:ring-0 cursor-pointer font-mono text-[#414141] outline-none" 
          value={currentScreen}
          onChange={(e) => navigate(e.target.value)}
        >
          <option value="trajectory_canvas">1. Trajectory Canvas</option>
          <option value="pacer_detail">2. Pacer Detail</option>
          <option value="subscribe_modal">3. Subscribe Modal</option>
          <option value="teams_chat_nudge">4. Teams Chat Nudge</option>
          <option value="milestone_celebration">5. Milestone Celebration</option>
          <option value="advisor_coach_view">6. Advisor Coach View</option>
        </select>
      </div>

      <AnimatePresence mode="wait">
        <motion.div 
          key={currentScreen}
          initial={{ opacity: 0, filter: 'blur(4px)' }}
          animate={{ opacity: 1, filter: 'blur(0px)' }}
          exit={{ opacity: 0, filter: 'blur(4px)' }}
          transition={{ duration: 0.3 }}
          className="flex-1 h-full"
        >
          {renderScreen()}
        </motion.div>
      </AnimatePresence>
    </div>
  );
};

